questionvariables.text:
/* Randomize radius and height around 40 (±5) */
r: rand_with_step(7,77,7); /* radius between 35 and 45 cm */
h: 35 + rand(11); /* height between 35 and 45 cm */

/* Step 1: Curved surface area of cylinder */
R_H:r*h;
CSA_cyl: 2*22/7*r*h;
CSA_cyl_val: float(CSA_cyl);


/* Step 2: Curved surface area of hemisphere */
R:r^2;
CSA_hemi: 2*22/7*(r^2);
CSA_hemi_val: float(CSA_hemi);

/* Step 3: Total external surface area */
Total_SA: CSA_cyl + CSA_hemi;
Total_SA_val: float(Total_SA);

/*Common student mistake*/

/*Mistake 1: Using the surface area of a whole cylinder (2 pi (r^2)+ 2 pi r h) instead of the curved surface of the cylinder(2 pi r h)*/

whole_cylinder_mistake:CSA_hemi+(2*22/7*(r^2)+2*22/7*r*h);
